parameters.jsCode:
const input = $input.first().json;
const callId = typeof input.call_id === 'string' ? input.call_id.trim() : '';
const appointmentStart = typeof input.appointment_start === 'string' ? input.appointment_start.trim() : '';
if (input.booking_succeeded !== true || !callId || !appointmentStart) return [];
const appointment = new Date(appointmentStart);
if (Number.isNaN(appointment.getTime())) return [];
const eventId = ('wondora' + callId + appointmentStart).toLowerCase().replace(/[^a-v0-9]/g, '').slice(0, 100);
const formatEastern = (value) => {
  if (!value) return 'Unavailable';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return 'Unavailable';
  return new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit', second: '2-digit', hour12: true, timeZoneName: 'short' }).format(date);
};
const duration = Number(input.call_duration_seconds || 0);
const completionDetails = [
  'CALL COMPLETION DETAILS',
  `Call completed: ${formatEastern(input.call_ended_at)}`,
  `Call duration: ${duration > 0 ? duration + ' seconds' : 'Unavailable'}`,
  `Call summary: ${input.call_summary || 'Unavailable'}`,
  `Client call view: ${input.call_summary_link || 'https://docs.google.com/spreadsheets/d/19ekskZGExeGti_9hSGJaCeaOcB3G0E1vxYg9I_yi3no/edit?gid=1129582252#gid=1129582252'}`,
  `Full recording: ${input.recording_url || 'Unavailable'}`,
].join('\n');
return [{ json: { ...input, calendar_event_id: eventId, completion_details: completionDetails } }];
